var currentOrg = 'coe';
var currentPhoto = 0;
var orgPhotoCache = {};
var orgPhotoDisplayedSrc = '';

function preloadOrgPhotos(photos) {
  photos.forEach(function (src) {
    if (orgPhotoCache[src]) return;
    var img = new Image();
    img.decoding = 'async';
    img.src = src;
    orgPhotoCache[src] = img;
  });
}

function selectOrg(id) {
  currentOrg = id;
  currentPhoto = 0;
  orgPhotoDisplayedSrc = '';
  document.querySelectorAll('.org-tab').forEach(function (tab) {
    tab.classList.toggle('active', tab.dataset.org === id);
  });
  preloadOrgPhotos(orgsData[id].photos);
  renderOrgPanel();
}

function initOrgFromHash() {
  var hash = window.location.hash;
  if (hash === '#events') {
    var events = document.getElementById('events');
    if (events) {
      setTimeout(function () {
        events.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 100);
    }
    return;
  }
  if (!hash.startsWith('#clubs-')) return;
  var id = hash.slice(7);
  if (!orgsData[id]) return;
  selectOrg(id);
  var tab = document.getElementById('clubs-' + id);
  if (tab) {
    setTimeout(function () {
      tab.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }, 100);
  }
}

window.addEventListener('hashchange', initOrgFromHash);

function orgCarouselNav(key, dir) {
  var photos = orgsData[currentOrg].photos;
  if (photos.length < 2) return;
  currentPhoto = (currentPhoto + dir + photos.length) % photos.length;
  renderOrgPhoto();
}

function renderOrgPhoto() {
  var data = orgsData[currentOrg];
  var display = document.getElementById('orgPhotoDisplay');
  var counter = document.getElementById('orgPhotoCounter');
  var prevBtn = document.getElementById('orgPhotoPrev');
  var nextBtn = document.getElementById('orgPhotoNext');
  var hasMultiple = data.photos.length > 1;
  prevBtn.style.display = hasMultiple ? '' : 'none';
  nextBtn.style.display = hasMultiple ? '' : 'none';
  var frame = display.parentElement;
  frame.classList.remove('landscape');
  if (data.photos.length) {
    var src = data.photos[currentPhoto];
    var img = display.querySelector('img');
    if (!img) {
      display.innerHTML = '';
      img = document.createElement('img');
      img.alt = '';
      img.decoding = 'async';
      display.appendChild(img);
    }
    counter.style.display = hasMultiple ? '' : 'none';
    if (hasMultiple) {
      document.getElementById('orgPhotoCurrent').textContent = currentPhoto + 1;
      document.getElementById('orgPhotoTotal').textContent = data.photos.length;
    }
    var applyOrientation = function () {
      frame.classList.toggle('landscape', img.naturalWidth > img.naturalHeight);
    };
    if (orgPhotoDisplayedSrc !== src) {
      orgPhotoDisplayedSrc = src;
      img.onload = applyOrientation;
      img.src = src;
      if (img.complete && img.naturalWidth) applyOrientation();
    } else if (img.complete && img.naturalWidth) {
      applyOrientation();
    }
  } else {
    orgPhotoDisplayedSrc = '';
    display.innerHTML = '<div class="org-photo-placeholder">Photos coming soon</div>';
    counter.style.display = 'none';
  }
}

function renderOrgPanel() {
  renderOrgPhoto();
  var data = orgsData[currentOrg];
  document.getElementById('orgPanelTitle').textContent = data.role;
  document.getElementById('orgPanelRole').textContent = data.name;
  document.getElementById('orgPanelDate').textContent = data.date;
  var desc = document.getElementById('orgPanelDesc');
  desc.innerHTML = '';
  data.description.forEach(function (paragraph) {
    var p = document.createElement('p');
    p.textContent = paragraph;
    desc.appendChild(p);
  });
  var ctas = document.getElementById('orgPanelCtas');
  ctas.innerHTML = '';
  (data.ctas || []).forEach(function (cta) {
    var a = document.createElement('a');
    a.className = 'org-panel-cta';
    a.href = cta.href;
    a.textContent = cta.label;
    ctas.appendChild(a);
  });
}

