function initBhCarousel(root, photos, opts) {
  opts = opts || {};
  var secondsPerPhoto = opts.secondsPerPhoto || 6; // continuous drift pace
  var alt = opts.alt || 'Photo';
  var filters = opts.filters || {};
  var classes = opts.classes || {}; // src -> extra class name for the slide

  var N = photos.length;
  var rendered = photos.concat(photos); // two copies for a seamless continuous loop

  var viewport = root.querySelector('.bh-carousel-viewport');
  var track = root.querySelector('.bh-carousel-track');
  var prevBtn = opts.prevBtn || root.querySelector('.bh-carousel-arrow--prev');
  var nextBtn = opts.nextBtn || root.querySelector('.bh-carousel-arrow--next');

  rendered.forEach(function(src) {
    var slide = document.createElement('div');
    slide.className = 'bh-carousel-slide';
    if (classes[src]) slide.classList.add(classes[src]);
    var inner = document.createElement('div');
    inner.className = 'bh-carousel-slide-inner';
    var img = document.createElement('img');
    img.src = src;
    img.alt = alt;
    img.loading = 'lazy';
    if (filters[src]) img.style.filter = filters[src];
    inner.appendChild(img);
    slide.appendChild(inner);
    track.appendChild(slide);
  });

  var widths = []; // per-slide widths for one set (index 0..N-1), in px
  var cumulative = [0]; // prefix sums of widths, length N+1
  var singleSetWidth = 0;
  var speed = 0; // px per ms
  var offset = 0; // current translateX, in (-singleSetWidth, 0]
  var hovering = false; // mouse is over the photos or arrows
  var jumping = false; // an arrow jump is settling
  var paused = false;
  var lastTime = null;

  function updatePaused() {
    paused = hovering || jumping;
  }

  function measure() {
    widths = [];
    cumulative = [0];
    for (var i = 0; i < N; i++) {
      var w = track.children[i].getBoundingClientRect().width;
      widths.push(w);
      cumulative.push(cumulative[i] + w);
    }
    singleSetWidth = cumulative[N];
    speed = singleSetWidth / (N * secondsPerPhoto * 1000);
  }

  function setTransform() {
    track.style.transform = 'translateX(' + offset + 'px)';
  }

  // Used for jumps (arrows/settle), where we need to toggle the
  // transition on/off without it animating the wrong change.
  function applyTransform(withTransition) {
    track.style.transition = withTransition ? 'transform 0.4s ease' : 'none';
    setTransform();
    if (!withTransition) track.getBoundingClientRect(); // force reflow
  }

  function settle() {
    jumping = false;
    updatePaused();
    if (offset <= -singleSetWidth) offset += singleSetWidth;
    if (offset > 0) offset -= singleSetWidth;
    applyTransform(false);
  }

  // Index of the slide currently sitting at (or just past) the viewport's left edge.
  function currentIndex() {
    var pos = ((-offset) % singleSetWidth + singleSetWidth) % singleSetWidth;
    for (var i = 0; i < N; i++) {
      if (pos < cumulative[i + 1] - 0.5) return i;
    }
    return 0;
  }

  function nudge(direction) {
    jumping = true;
    updatePaused();
    var i = currentIndex();
    if (direction > 0) {
      offset -= widths[i];
    } else {
      offset += widths[(i - 1 + N) % N];
    }
    applyTransform(true);
    setTimeout(settle, 420);
  }

  function tick(now) {
    if (lastTime === null) lastTime = now;
    var dt = now - lastTime;
    lastTime = now;
    if (!paused) {
      offset -= speed * dt;
      if (offset <= -singleSetWidth) offset += singleSetWidth;
      setTransform();
    }
    requestAnimationFrame(tick);
  }

  prevBtn.addEventListener('click', function() { nudge(-1); });
  nextBtn.addEventListener('click', function() { nudge(1); });

  // Only pause for hover over the photos or the arrow buttons.
  [viewport, prevBtn, nextBtn].forEach(function(el) {
    el.addEventListener('mouseenter', function() { hovering = true; updatePaused(); });
    el.addEventListener('mouseleave', function() { hovering = false; updatePaused(); });
  });

  window.addEventListener('resize', function() {
    var old = singleSetWidth;
    measure();
    if (old) offset = offset * (singleSetWidth / old);
    applyTransform(false);
  });

  // Wait for first-set images so width: auto resolves before measuring speed.
  var firstSetImgs = [];
  for (var fi = 0; fi < N; fi++) {
    var firstImg = track.children[fi].querySelector('img');
    firstImg.loading = 'eager';
    firstSetImgs.push(firstImg);
  }
  function remeasureFromLoads() {
    measure();
    applyTransform(false);
  }
  firstSetImgs.forEach(function(img) {
    if (img.complete && img.naturalWidth > 0) remeasureFromLoads();
    else {
      img.addEventListener('load', remeasureFromLoads);
      img.addEventListener('error', remeasureFromLoads);
    }
  });

  measure();
  applyTransform(false);
  requestAnimationFrame(tick);
}

