(function() {
  function initIjCarousel(root, photos, opts) {
    opts = opts || {};
    var secondsPerPhoto = opts.secondsPerPhoto || 6;
    var alt = opts.alt || 'Photo';
    var transforms = opts.transforms || {};
    var N = photos.length;
    var rendered = photos.concat(photos);
    var viewport = root.querySelector('.ij-carousel-viewport');
    var track = root.querySelector('.ij-carousel-track');
    var prevBtn = opts.prevBtn || root.querySelector('.ij-carousel-arrow--prev');
    var nextBtn = opts.nextBtn || root.querySelector('.ij-carousel-arrow--next');
    rendered.forEach(function(src) {
      var slide = document.createElement('div');
      slide.className = 'ij-carousel-slide';
      var inner = document.createElement('div');
      inner.className = 'ij-carousel-slide-inner';
      var img = document.createElement('img');
      img.src = src; img.alt = alt; img.loading = 'lazy';
      if (transforms[src]) img.style.transform = transforms[src];
      inner.appendChild(img);
      slide.appendChild(inner);
      track.appendChild(slide);
    });
    var widths = [], cumulative = [0], singleSetWidth = 0, speed = 0;
    var offset = 0, hovering = false, jumping = false, paused = false, lastTime = null;
    function updatePaused() { paused = hovering || jumping; }
    function measure() {
      widths = []; cumulative = [0];
      for (var i = 0; i < N; i++) {
        var w = track.children[i].getBoundingClientRect().width;
        widths.push(w); cumulative.push(cumulative[i] + w);
      }
      singleSetWidth = cumulative[N];
      speed = singleSetWidth / (N * secondsPerPhoto * 1000);
    }
    function setTransform() { track.style.transform = 'translateX(' + offset + 'px)'; }
    function applyTransform(t) {
      track.style.transition = t ? 'transform 0.4s ease' : 'none';
      setTransform();
      if (!t) track.getBoundingClientRect();
    }
    function settle() {
      jumping = false; updatePaused();
      if (offset <= -singleSetWidth) offset += singleSetWidth;
      if (offset > 0) offset -= singleSetWidth;
      applyTransform(false);
    }
    function currentIndex() {
      var pos = ((-offset) % singleSetWidth + singleSetWidth) % singleSetWidth;
      for (var i = 0; i < N; i++) { if (pos < cumulative[i+1] - 0.5) return i; }
      return 0;
    }
    function nudge(dir) {
      jumping = true; updatePaused();
      var i = currentIndex();
      if (dir > 0) { offset -= widths[i]; } else { offset += widths[(i-1+N)%N]; }
      applyTransform(true);
      setTimeout(settle, 420);
    }
    function tick(now) {
      if (lastTime === null) lastTime = now;
      var dt = now - lastTime; lastTime = now;
      if (!paused) {
        offset -= speed * dt;
        if (offset <= -singleSetWidth) offset += singleSetWidth;
        setTransform();
      }
      requestAnimationFrame(tick);
    }
    prevBtn.addEventListener('click', function() { nudge(-1); });
    nextBtn.addEventListener('click', function() { nudge(1); });
    [viewport, prevBtn, nextBtn].forEach(function(el) {
      el.addEventListener('mouseenter', function() { hovering = true; updatePaused(); });
      el.addEventListener('mouseleave', function() { hovering = false; updatePaused(); });
    });
    window.addEventListener('resize', function() {
      var old = singleSetWidth; measure();
      if (old) offset = offset * (singleSetWidth / old);
      applyTransform(false);
    });
    // Wait for images to load so width: auto resolves before measuring
    var imgs = track.querySelectorAll('img');
    var loaded = 0;
    function onImgLoad() {
      loaded++;
      if (loaded === imgs.length) { measure(); applyTransform(false); }
    }
    imgs.forEach(function(img) {
      if (img.complete) { onImgLoad(); } else { img.addEventListener('load', onImgLoad); }
    });
    measure(); applyTransform(false); requestAnimationFrame(tick);
  }

  var photos = [
    'innovation-26/IMG_2967.jpg',
    'innovation-26/IMG_2520.JPG',
    'innovation-26/IMG_2521.JPG',
    'innovation-26/IMG_2522.JPG',
